"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[1394],{51394:a=>{a.exports=JSON.parse('{"slug":"nobel-ekonomika-2026-holl-vudford-ozhidaniya","locale":"zh","title":"诺贝尔经济学奖表彰央行用于理解居民预期的模型","description":"霍尔与伍德福德获2026年经济学奖。他们的模型解释为何俄罗斯通胀7.17%时关键利率仍为14%。","blocks":[{"id":"b001","kind":"paragraph","text":"诺贝尔委员会于2026年十月12日把经济学奖授予斯坦福大学罗伯特\xb7霍尔和哥伦比亚大学迈克尔\xb7伍德福德，理由是“宏观经济稳定的微观经济基础”。两人分享12百万瑞典克朗，约$1.2百万。委员会称，由其研究发展而来的模型已被全球央行和财政部门采用。"},{"id":"b002","kind":"paragraph","text":"稳定政策即央行和政府在经济过热、物价上涨时降温，在失业上升时刺激。近100年前，凯恩斯提出通过通胀、失业和消费等总量之间的关系计算。但1970年代这些关系失灵，美国试图扩需求降失业，却同时遭遇失业与高通胀。"},{"id":"b003","kind":"paragraph","text":"霍尔与伍德福德从个人和企业决策自下而上建模。霍尔1978年发展弗里德曼思想，表明支出基于未来预期收入，而非只看当前工资。核心结论：经济不仅回应发生了什么，也回应人们预期什么。央行解释计划能够改变预期。"},{"id":"b004","kind":"paragraph","text":"房东最能说明预期如何推价。若预期一年涨14%，会立即上调房租，而非等一年。租户也预期涨价，于是提高服务价，结果价格因人们预期上涨而上涨。这称通胀预期。"},{"id":"b005","kind":"paragraph","text":"俄罗斯目前差距很大。经济发展部截至十月5日估年通胀7.17%，而央行九月调查居民预期未来一年14.2%。央行每月公布并在决策时关注该调查。居民预期涨幅近实际2倍时，监管机构担心燃料等一次性跳涨变成持续通胀。"},{"id":"b006","kind":"paragraph","text":"普通人可得的含义：央行利率不只取决于今天通胀，也取决于人们相信什么。预期高时，贷款仍贵、存款有收益。等信用购买要付时间成本，现在借要付高利息。十月23日决定会像关注实际价格一样关注居民预期。"},{"id":"b007","kind":"heading","text":"2026年诺贝尔经济学奖由谁获得？"},{"id":"b008","kind":"paragraph","text":"美国经济学家斯坦福的罗伯特\xb7霍尔、哥伦比亚的迈克尔\xb7伍德福德。2026年十月12日因“宏观经济稳定的微观基础”获奖，分享12百万瑞典克朗。"},{"id":"b009","kind":"heading","text":"2026年经济学奖表彰什么？"},{"id":"b010","kind":"paragraph","text":"表彰从个人和企业决策构建经济、并把未来预期纳入决策的模型。央行及财政部据此判断何时刺激、何时降温。"},{"id":"b011","kind":"heading","text":"这与俄罗斯央行利率有何关系？"},{"id":"b012","kind":"paragraph","text":"获奖模型解释预期如何影响物价。俄罗斯同比7.17%，居民预期14.2%。高预期可能让一次性上涨持续，因此央行不急于下调14%利率。"}],"sources":[{"label":"罗伯特\xb7霍尔与迈克尔\xb7伍德福德获诺贝尔经济学奖","url":"https://www.cnbc.com/2026/10/12/nobel-economics-prize-winner-woodford-hall.html"},{"label":"谁获得经济学奖、因何获奖","url":"https://www.vedomosti.ru/economics/articles/2026/10/13/1236487-kto-poluchil-nobelevskuyu-premiyu-po-ekonomike"},{"label":"新凯恩斯主义的胜利：今年经济学奖的意义","url":"https://thebell.io/triumf-novokeynsianstva-za-chto-dali-nobelya-po-ekonomike-v-etom-godu"},{"label":"2026年九月通胀预期和消费者情绪","url":"https://www.cbr.ru/analytics/dkp/inflationary_expectations/Infl_exp_26-09/"},{"label":"俄罗斯九月29日至十月5日通胀","url":"https://www.vedomosti.ru/economics/news/2026/10/07/1235202-inflyatsiya-v-rossii"}],"sourceBodySha256":"e13ad2b2a2ae1a90ea84da9b64778750943d70fe565916eb1fb9a1a889724ba6"}')}}]);